#include <Std_Types.h>          /* AUTOSAR standard types */
#include <TSArch_Names.h>       /* defines for architecture names */

/*==================[macros]=================================================*/

/*------------------[macros set on the command line]-------------------------*/
#define TS_ARCH_FAMILY
#define TS_ARCH_DERIVATE

#if (!defined TS_ARCH_FAMILY)
/** \brief Provides the target architecture family name
 *
 * This define must be set on the commandline
 * */
#error TS_ARCH_FAMILY must be defined on commandline
#endif /* if (!defined TS_ARCH_FAMILY) */

#if (!defined TS_ARCH_DERIVATE)
/** \brief Provides the target derivate name
 *
 * This define must be set on the commandline
 * */
#error TS_ARCH_DERIVATE must be defined on commandline
#endif /* if (!defined TS_ARCH_DERIVATE) */

#if (!defined TS_USE_INLINE_FUNC)
/** \brief Determines if that \p inline keyword is to be used (if present)
 *
 * This define must be set on the commandline
 *
 * This switch enables/disables the \p inline keyword for functions.
 * This keyword is not part of the ISO-C:1989 and it is unclear if
 * it can be used or not.
 *
 * If set to 1 \p TSAutosar.h may provide the \p inline keyword
 * */
#define TS_USE_INLINE_FUNC 1U
#endif /* if (!defined TS_USE_INLINE_FUNC) */

/** \brief Determines if that \p static keyword is to be used for funcs
 *
 * This define must be set on the commandline
 *
 * This switch enables/disables the \p static keyword for functions.
 * This keyword is not part of the ISO-C:1989 and it is unclear if
 * it can be used or not.
 *
 * If set to 1 \p TSAutosar.h may provide the \p static keyword
 * */
#if (!defined TS_USE_STATIC_FUNC)
#define TS_USE_STATIC_FUNC 1U
#endif /* if (!defined TS_USE_STATIC_FUNC) */

/** \brief Determines if that \p static keyword is to be used for vars
 *
 * This define must be set on the commandline
 *
 * This switch enables/disables the \p static keyword for variables.
 * This keyword is not part of the ISO-C:1989 and it is unclear if
 * it can be used or not.
 *
 * If set to 1 \p TSAutosar.h may provide the \p static keyword
 * */
#if (!defined TS_USE_STATIC_VAR)
#define TS_USE_STATIC_VAR 1U
#endif /* if (!defined TS_USE_STATIC_VAR) */

/** \brief Determines if det calls should be dispatched
 *
 * This define must be set on the commandline
 *
 * If set to 1 errors are reported via the det
 * */
#if (!defined TS_DEV_ERROR_DETECT)
#define TS_DEV_ERROR_DETECT 1U
#endif /* if (!defined TS_DEV_ERROR_DETECT) */


/** \brief abstraction of the \p static keyword for functions
 *
 * This switch enables/disables the keyword \p static for functions.
 * Large modules hide most of their functions by declaring them
 * as \p static functions.
 *
 * This can be a problem for debugging, e.g. if the debugger has
 * problems with breakpoints on static functions.
 *
 * This can also be a problem for testing if the module tester wants
 * to call each function separately. */
#if (defined TS_STATIC_FUNC) /* guard to prevent double declaration */
#error TS_STATIC_FUNC already defined
#endif /* if (defined TS_STATIC_FUNC) */

#if (TS_USE_STATIC_FUNC == 1U)
#define TS_STATIC_FUNC static
#else
#define TS_STATIC_FUNC
#endif /* if (TS_USE_STATIC_FUNC == 1U) */


/** \brief abstraction of the \p static keyword for variables
 *
 * This switch enables/disables the keyword \p static for variables.
 * Large modules hide most of their internal variables by declaring
 * them as \p static variables.
 *
 * This can be a problem for debugging, e.g. if the debugger has
 * problems with inspecting local data.
 *
 * This can also be a problem for testing it the module tester wants
 * to operate in internal variables directly. */
#if (defined TS_STATIC_VAR) /* guard to prevent double declaration */
#error TS_STATIC_VAR already defined
#endif /* if (defined TS_STATIC_VAR) */

#if (TS_USE_STATIC_VAR == 1U)
#define TS_STATIC_VAR static
#else
#define TS_STATIC_VAR
#endif /* if (TS_USE_STATIC_VAR == 1U) */

/** \brief abstraction of the \p inline keyword for functions
 *
 * This switch enables/disables the \p inline keyword for functions.
 * This keyword is not part of the ISO-C:1989 and it is unclear if
 * it can be used or not.
 *
 * */
#if (defined TS_INLINE_FUNC)
#error TS_INLINE_FUNC already defined
#endif /* if (defined TS_INLINE_FUNC) */

#if (TS_USE_INLINE_FUNC == 1U)
#define TS_INLINE_FUNC inline
#else
#define TS_INLINE_FUNC
#endif /* if (TS_USE_INLINE_FUNC == 1U) */

